                int draww = (img.getWidth() * drawh) / img.getHeight();
                int delta = (c.getWidth() - draww) / 2;
                c.drawBitmap(img, new Rect(0, 0, img.getWidth(), img.getHeight()), new Rect(delta, 0, draww + delta, drawh), new Paint());
