            int draww2 = c.getWidth();
            int drawh2 = (img.getHeight() * draww2) / img.getWidth();
            int delta2 = c.getHeight() - drawh2;
            c.drawBitmap(img, new Rect(0, 0, img.getWidth(), img.getHeight()), new Rect(0, delta2, draww2, drawh2 + delta2), new Paint());
