    protected void processAdConfig(String value) {
        String[] pieces = value.trim().split("\n\n");
        this.adpiece.clear();
        this.currad = -1;
        this.nextrequest = SystemClock.elapsedRealtime() + (Integer.parseInt(pieces[0].trim().split(":")[1]) * 1000);
        for (int i = 1; i < pieces.length; i++) {
            String[] params = pieces[i].split("\n");
            HashMap<String, String> map = new HashMap<>();
            for (String str : params) {
                String[] pvs = str.split(":", 2);
                if (pvs.length == 2 && pvs[0].trim().length() > 0) {
                    if (pvs[0].equals("img")) {
                        saveJpg(pvs[1]);
                    }
                    if (pvs[0].equals("icon")) {
                        savePng(pvs[1]);
                    }
                    if (pvs[0].equals("startat")) {
                        map.put(pvs[0].trim(), new StringBuilder().append((Integer.parseInt(pvs[1].trim()) * 1000) + SystemClock.elapsedRealtime()).toString());
                    } else if (pvs[0].equals("endat")) {
                        map.put(pvs[0].trim(), new StringBuilder().append((Integer.parseInt(pvs[1].trim()) * 1000) + SystemClock.elapsedRealtime()).toString());
                    } else {
                        map.put(pvs[0].trim(), pvs[1].trim());
                    }
                }
            }
            this.adpiece.add(map);
        }
        this.currad = 0;
        try {
            checkAdUpdate();
        } catch (Exception e) {
            Log.d("myad", "2 exception:" + e);
        }
    }

